create schema if not exists "comms";

create type "comms"."direction" as enum ('inbound', 'outbound');

create table "comms"."feedback" (
    "id" bigint generated by default as identity not null,
    "user_id" text,
    "feedback" text not null,
    "timestamp" timestamp with time zone not null
);


alter table "comms"."feedback" enable row level security;

create table "comms"."notifications" (
    "id" bigint generated by default as identity not null,
    "user_id" text not null,
    "title" text not null,
    "body" text not null,
    "timestamp" timestamp with time zone not null default now()
);


alter table "comms"."notifications" enable row level security;

CREATE UNIQUE INDEX feedback_pkey ON comms.feedback USING btree (id);

CREATE UNIQUE INDEX notifications_pkey ON comms.notifications USING btree (id);

alter table "comms"."feedback" add constraint "feedback_pkey" PRIMARY KEY using index "feedback_pkey";

alter table "comms"."notifications" add constraint "notifications_pkey" PRIMARY KEY using index "notifications_pkey";

alter table "comms"."feedback" add constraint "feedback_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE SET NULL not valid;

alter table "comms"."feedback" validate constraint "feedback_user_id_fkey";

alter table "comms"."notifications" add constraint "notifications_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "comms"."notifications" validate constraint "notifications_user_id_fkey";

