create schema if not exists "groups";

create table "groups"."group_activity" (
    "id" uuid not null default gen_random_uuid(),
    "group_id" uuid not null,
    "user_id" text not null,
    "timestamp" timestamp with time zone not null default now(),
    "activity" group_activity_type not null default 'joined'::group_activity_type
);


alter table "groups"."group_activity" enable row level security;

create table "groups"."group_members" (
    "id" uuid not null default gen_random_uuid(),
    "group_id" uuid not null,
    "user_id" text not null
);


alter table "groups"."group_members" enable row level security;

create table "groups"."group_notes" (
    "id" uuid not null default gen_random_uuid(),
    "group_id" uuid not null,
    "to_member_id" text not null,
    "from_member_id" text not null,
    "message" text not null,
    "timestamp" timestamp with time zone not null default now()
);


alter table "groups"."group_notes" enable row level security;

create table "groups"."group_pings" (
    "id" uuid not null default gen_random_uuid(),
    "from_user_id" text not null default now(),
    "to_user_id" text not null,
    "group_id" uuid not null,
    "timestamp" timestamp with time zone not null default now()
);


alter table "groups"."group_pings" enable row level security;

create table "groups"."group_subscriptions" (
    "id" uuid not null default gen_random_uuid(),
    "group_id" uuid not null,
    "user_id" text not null,
    "subscribed_to" text not null,
    "timestamp" timestamp with time zone not null default now()
);


alter table "groups"."group_subscriptions" enable row level security;

create table "groups"."groups" (
    "id" uuid not null default gen_random_uuid(),
    "name" text not null,
    "hue" numeric not null
);


alter table "groups"."groups" enable row level security;

CREATE UNIQUE INDEX group_activity_pkey ON groups.group_activity USING btree (id);

CREATE UNIQUE INDEX group_members_pkey ON groups.group_members USING btree (id);

CREATE UNIQUE INDEX group_notes_pkey ON groups.group_notes USING btree (id);

CREATE UNIQUE INDEX group_notes_unique_constraint ON groups.group_notes USING btree (group_id, from_member_id, to_member_id, "timestamp");

CREATE UNIQUE INDEX group_pings_pkey ON groups.group_pings USING btree (id);

CREATE UNIQUE INDEX group_subscriptions_pkey ON groups.group_subscriptions USING btree (id);

CREATE UNIQUE INDEX groups_pkey ON groups.groups USING btree (id);

CREATE UNIQUE INDEX unique_group_activity ON groups.group_activity USING btree (group_id, user_id, "timestamp");

CREATE UNIQUE INDEX unique_group_user ON groups.group_members USING btree (group_id, user_id);

